#!/usr/bin/env node
/**
 * The RFC bookkeeping: a new document, the two listings, and the state of play.
 *
 *   node build/rfc.mjs new --title "…" [--short …] [--settles …] [--bis NNNN]
 *   node build/rfc.mjs index [--check]
 *   node build/rfc.mjs status [--json]
 *
 * Called through `task rfc:new`, `task rfc:index`, `task rfc:index:check` and
 * `task rfc:status`.
 *
 * Why generated. An RFC's number, name, status and one-line summary were each
 * written in three places: the document, the table on `/rfc/`, and the `/rfc/`
 * sidebar in `.vitepress/config.ts`. Nothing compared them, and the drift was
 * already there when this was written — the index prose said "eight of the
 * fifteen below", of seventeen documents, and the index and the sidebar
 * disagreed about what four of them were called. A page that mislabels the
 * project's own design history is the same defect class RFC 0005 was about.
 *
 * So the RFC's header table is the only home for those facts, `rfc:index`
 * rewrites the two listings from it, and `rfc:index:check` fails the docs gate
 * when they have drifted. Only the block between the markers is replaced; the
 * prose around it — which argues about what these documents mean to each
 * other — stays hand-written.
 */
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

import { readRfcs } from "./rfc-meta.mjs";

const DOCS = fileURLToPath(new URL("..", import.meta.url));
const RFC_DIR = join(DOCS, "rfc");
const INDEX = join(RFC_DIR, "index.md");
const CONFIG = join(DOCS, ".vitepress", "config.ts");
const TEMPLATE = join(DOCS, "internal", "0000-rfc-template.md");

const NOTE = "generated by `task rfc:index` from each RFC's header table — do not edit by hand";
const INDEX_BEGIN = `<!-- BEGIN rfc-index — ${NOTE} -->`;
const INDEX_END = "<!-- END rfc-index -->";
const SIDEBAR_BEGIN = `// BEGIN rfc-sidebar — ${NOTE}`;
const SIDEBAR_END = "// END rfc-sidebar";

/* ── The two generated listings ───────────────────────────────────────────── */

const WORDS = [
  "no", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
  "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
  "seventeen", "eighteen", "nineteen", "twenty",
];
const count = (n) => (n < WORDS.length ? WORDS[n] : String(n));

/** Wrap to the width the rest of the documentation's prose is written to. */
function wrap(text, width = 80) {
  const lines = [];
  let line = "";
  for (const word of text.split(" ")) {
    if (line && `${line} ${word}`.length > width) {
      lines.push(line);
      line = word;
    } else {
      line = line ? `${line} ${word}` : word;
    }
  }
  if (line) lines.push(line);
  return lines.join("\n");
}

/**
 * "Of the seventeen below, eight are implemented, three are in review …" — the
 * sentence that was wrong on the published page, in the plural the reader sees.
 */
function summary(rfcs) {
  const by = (state) => rfcs.filter((r) => r.status.state.startsWith(state)).length;
  const parts = [
    [by("Implemented"), "implemented"],
    [by("Accepted"), "accepted"],
    [by("In review"), "in review"],
    [by("Draft"), (n) => (n === 1 ? "a draft" : "drafts")],
    [by("Rejected"), "rejected"],
    [by("Superseded"), "superseded"],
  ]
    .filter(([n]) => n > 0)
    .map(([n, label]) => {
      const word = typeof label === "function" ? label(n) : label;
      return `${count(n)} ${n === 1 ? "is" : "are"} ${word}`;
    });

  const list =
    parts.length > 1 ? `${parts.slice(0, -1).join(", ")} and ${parts.at(-1)}` : parts[0];
  return wrap(`Of the ${count(rfcs.length)} below, ${list}.`);
}

function indexBlock(rfcs) {
  const rows = rfcs.map(
    (r) =>
      `| [${r.id} — ${r.short}](/rfc/${r.slug}) | ${r.status.state} | ${r.settles} |`,
  );
  return [
    summary(rfcs),
    "",
    "| RFC | Status | What it settles |",
    "| --- | --- | --- |",
    ...rows,
  ].join("\n");
}

function sidebarBlock(rfcs) {
  const pad = " ".repeat(12);
  return rfcs
    .map((r) =>
      [
        `${pad}{`,
        `${pad}  text: "${r.id} — ${r.short}",`,
        `${pad}  link: "/rfc/${r.slug}",`,
        `${pad}},`,
      ].join("\n"),
    )
    .join("\n");
}

/**
 * Replace everything between two marker lines, keeping the markers — and the
 * closing marker's own indentation, since one of them sits inside a TypeScript
 * array literal.
 */
function replaceBlock(text, begin, end, body, where) {
  const from = text.indexOf(begin);
  const to = text.indexOf(end, from);
  if (from === -1 || to === -1) {
    throw new Error(
      `${where}: missing the ${begin.includes("rfc-index") ? "rfc-index" : "rfc-sidebar"} ` +
        `markers. The generated block is delimited by them; restore both lines.`,
    );
  }
  const indent = text.slice(text.lastIndexOf("\n", to) + 1, to);
  return text.slice(0, from + begin.length) + "\n" + body + "\n" + indent + text.slice(to);
}

function renderIndex(rfcs) {
  return replaceBlock(
    readFileSync(INDEX, "utf8"),
    INDEX_BEGIN,
    INDEX_END,
    // Blank lines inside the markers, so the block reads as markdown rather
    // than as a paragraph that happens to start with a comment.
    `\n${indexBlock(rfcs)}\n`,
    "docs/rfc/index.md",
  );
}

function renderConfig(rfcs) {
  return replaceBlock(
    readFileSync(CONFIG, "utf8"),
    SIDEBAR_BEGIN,
    SIDEBAR_END,
    sidebarBlock(rfcs),
    "docs/.vitepress/config.ts",
  );
}

function cmdIndex({ check }) {
  const rfcs = readRfcs(RFC_DIR);
  const targets = [
    ["docs/rfc/index.md", INDEX, renderIndex(rfcs)],
    ["docs/.vitepress/config.ts", CONFIG, renderConfig(rfcs)],
  ];

  if (check) {
    const stale = targets.filter(([, path, next]) => readFileSync(path, "utf8") !== next);
    if (stale.length) {
      console.error(
        `the /rfc/ listings have drifted from the documents: ` +
          `${stale.map(([name]) => name).join(", ")}\n` +
          `run 'task rfc:index' and commit the result`,
      );
      process.exit(1);
    }
    console.log(`the /rfc/ index and sidebar match the ${rfcs.length} documents`);
    return;
  }

  let written = 0;
  for (const [name, path, next] of targets) {
    if (readFileSync(path, "utf8") === next) continue;
    writeFileSync(path, next);
    console.log(`  rewrote ${name}`);
    written++;
  }
  console.log(
    written
      ? `${rfcs.length} RFCs listed`
      : `${rfcs.length} RFCs listed — both listings were already current`,
  );
}

/* ── The state of play ────────────────────────────────────────────────────── */

function cmdStatus({ json }) {
  const rfcs = readRfcs(RFC_DIR);
  if (json) {
    console.log(JSON.stringify(rfcs, null, 2));
    return;
  }

  const width = Math.max(...rfcs.map((r) => r.short.length));
  console.log(`${"RFC".padEnd(9)}${"Status".padEnd(20)}${"Open".padEnd(6)}Name`);
  for (const r of rfcs) {
    // "Still open" empty and not settled: the template's own definition of
    // ready for sign-off, which is the one thing this report exists to surface.
    const ready = !r.status.settled && r.openQuestions === 0 ? "  ← no open questions" : "";
    const todo = /^TODO\b/.test(r.settles) ? "  ← Settles still says TODO" : "";
    console.log(
      (
        `${r.id.padEnd(9)}${r.status.state.padEnd(20)}` +
        `${String(r.openQuestions).padEnd(6)}${r.short.padEnd(width)}${ready}${todo}`
      ).trimEnd(),
    );
  }

  const settled = rfcs.filter((r) => r.status.settled).length;
  const open = rfcs.reduce((n, r) => n + r.openQuestions, 0);
  const owing = rfcs.filter((r) => r.openQuestions > 0).length;
  console.log(
    `\n${rfcs.length} RFCs — ${settled} settled, ${rfcs.length - settled} still proposals; ` +
      `${open} open question(s) across ${owing} document(s)`,
  );
}

/* ── What was put off ─────────────────────────────────────────────────────── */

/**
 * Every choice the RFCs took *not* to make, in one list.
 *
 * Two classes, and the difference is the whole point of the report. A
 * **deferral** is decided: somebody argued it, wrote why not now, and often
 * wrote what would reopen it. An **open question** is not: it sits under
 * "Still open" in a document that has not been signed off, and it is owed.
 * A deferral with no reopen condition is flagged, because that is the one
 * that quietly becomes a permanent hole.
 */
function cmdDeferred({ json }) {
  const rfcs = readRfcs(RFC_DIR);
  const deferred = rfcs.flatMap((r) =>
    r.deferrals.map((d) => ({ rfc: r.id, short: r.short, ...d })),
  );
  const owed = rfcs.filter((r) => r.openQuestions > 0);

  if (json) {
    console.log(
      JSON.stringify(
        { deferred, owed: owed.map((r) => ({ rfc: r.id, short: r.short, open: r.openQuestions })) },
        null,
        2,
      ),
    );
    return;
  }

  console.log("Deferred — decided, and not now\n");
  for (const d of deferred) {
    const name = d.lead.replace(/^Deferred[^:]*:[ \t]*/, "").replace(/^Deferred\b[, ]*/, "");
    // `trimEnd` rather than `/\s+$/`, which is retried from every position in
    // the line; the nested template it used to interpolate is a `lead` of its
    // own for the same reason a reader would ask for one.
    const lead = name ? `${name} — ` : "";
    console.log(`${d.rfc.padEnd(9)}${d.where}`);
    console.log(`         ${lead}${d.claim}`.trimEnd());
    if (!d.reopens) console.log("         (no reopen condition recorded)");
    console.log();
  }

  if (owed.length) {
    console.log("Still owed — under \"Still open\", in a document not yet settled\n");
    for (const r of owed) {
      console.log(`${r.id.padEnd(9)}${String(r.openQuestions).padEnd(3)}${r.short}`);
    }
    console.log();
  }

  const silent = deferred.filter((d) => !d.reopens).length;
  console.log(
    `${deferred.length} deferral(s) across ${new Set(deferred.map((d) => d.rfc)).size} document(s), ` +
      `${silent} with no reopen condition; ` +
      `${owed.reduce((n, r) => n + r.openQuestions, 0)} question(s) still owed across ${owed.length}`,
  );
}

/* ── A new document ───────────────────────────────────────────────────────── */

const kebab = (s) =>
  s
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");

/** Rewrite one `| Label | … |` row's value, keeping both columns' widths. */
function setRow(text, label, value) {
  const row = new RegExp(String.raw`^\|(\s*${label}\s*)\|([^|]*)\|[ \t]*$`, "m");
  if (!row.test(text)) throw new Error(`the template has no "| ${label} | … |" row`);
  return text.replace(row, (_, pad, cell) => {
    // The value column is ragged in the existing RFCs once the prose outgrows
    // it, so this pads up to the template's width and never trims below it.
    const body = ` ${value} `.padEnd(cell.length, " ");
    return `|${pad}|${body}|`;
  });
}

/**
 * The `git` to run, as an absolute path, or `null` when none of the standard
 * locations has one.
 *
 * Resolved from a fixed list rather than from `PATH`, because a `PATH` entry is
 * writable by whoever owns it and this file runs `git` on a developer's machine
 * with that developer's privileges — the shadowing that `javascript:S4036`
 * (CWE-426) is about. The list is ordered so a distro-managed `/usr/bin/git`
 * wins over a Homebrew prefix, which on macOS is chowned to the user.
 *
 * Resolved once: `task rfc:new` asks for two keys and the answer cannot change
 * between them.
 */
const GIT =
  ["/usr/bin/git", "/usr/local/bin/git", "/opt/homebrew/bin/git"].find(existsSync) ?? null;

/**
 * A value from `git config`, or `fallback` when git is absent, the key is unset
 * or the value is blank.
 *
 * Only the RFC template's Author line reads this, and only `task rfc:new`
 * writes that line, so an unusual git location costs one hand-edit of a
 * freshly-scaffolded file — the same cost as not having git configured at all,
 * which this already had to handle.
 */
function gitConfig(key, fallback) {
  if (!GIT) return fallback;
  try {
    return execFileSync(GIT, ["config", "--get", key], { encoding: "utf8" }).trim() || fallback;
  } catch {
    return fallback;
  }
}

function cmdNew(opts) {
  if (!opts.title) {
    console.error(
      'a title is required: task rfc:new TITLE="Signed URLs for the credential-less request"',
    );
    process.exit(2);
  }

  const rfcs = readRfcs(RFC_DIR);
  let id;
  if (opts.bis) {
    const num = Number(opts.bis);
    if (!rfcs.some((r) => r.num === num && !r.bis)) {
      console.error(`no RFC ${opts.bis} to write a bis of`);
      process.exit(2);
    }
    if (rfcs.some((r) => r.num === num && r.bis)) {
      console.error(`RFC ${String(num).padStart(4, "0")}-bis already exists`);
      process.exit(2);
    }
    id = `${String(num).padStart(4, "0")}-bis`;
  } else {
    // Numbers are never reused, even by a rejected or withdrawn RFC, so the
    // next one is one past the highest that has ever existed.
    id = String(Math.max(0, ...rfcs.map((r) => r.num)) + 1).padStart(4, "0");
  }

  const slug = `${id}-${kebab(opts.slug || opts.title)}`;
  const path = join(RFC_DIR, `${slug}.md`);
  if (existsSync(path)) {
    console.error(`${path} already exists`);
    process.exit(2);
  }

  const author =
    opts.author ||
    `${gitConfig("user.name", "Name")} <${gitConfig("user.email", "email")}>`;
  const created = opts.date || new Date().toISOString().slice(0, 10);

  let doc = readFileSync(TEMPLATE, "utf8");
  // The instructions for copying the form are not part of the copy.
  doc = doc.replace(/^<!--[\s\S]*?-->\n+/, "");
  doc = doc.replace(/^# RFC NNNN — <Title>$/m, `# RFC ${id} — ${opts.title}`);
  doc = setRow(doc, "Status", "Draft");
  doc = setRow(doc, "Short", opts.short || opts.title);
  doc = setRow(
    doc,
    "Settles",
    opts.settles || "TODO — one line: what this RFC settles, for the /rfc/ index",
  );
  doc = setRow(doc, "Author", author);
  doc = setRow(doc, "Created", created);
  if (opts.bis) {
    // A bis does not supersede its base — it carries what the base left, which
    // is what RFC 0004-bis's own `Complements` row says. Same row, so the two
    // read alike.
    const base = id.slice(0, 4);
    doc = doc.replace(
      /^\|(\s*Supersedes\s*)\|[^|]*\|[ \t]*$/m,
      (row, pad) =>
        `${row}\n|${" Complements".padEnd(pad.length, " ")}| RFC ${base} — <what this one carries of it> |`,
    );
  }

  writeFileSync(path, doc);
  console.log(`wrote docs/rfc/${slug}.md`);
  // Written straight into both listings: a published page in no sidebar is an
  // orphan, and `task docs:links` would fail on it at the end of the day
  // rather than at the start.
  cmdIndex({ check: false });
  if (!opts.settles) {
    console.log(
      `\nthe Settles row still says TODO — the /rfc/ table quotes it, ` +
        `so fill it in and rerun 'task rfc:index'`,
    );
  }
}

/* ── Arguments ────────────────────────────────────────────────────────────── */

const [command, ...rest] = process.argv.slice(2);
const opts = { check: false, json: false };
for (let i = 0; i < rest.length; i++) {
  const arg = rest[i];
  if (arg === "--check") opts.check = true;
  else if (arg === "--json") opts.json = true;
  else if (arg.startsWith("--")) opts[arg.slice(2)] = rest[++i];
}

try {
  if (command === "index") cmdIndex(opts);
  else if (command === "status") cmdStatus(opts);
  else if (command === "deferred") cmdDeferred(opts);
  else if (command === "new") cmdNew(opts);
  else {
    console.error("usage: rfc.mjs new|index|status|deferred  (see the header of this file)");
    process.exit(2);
  }
} catch (err) {
  console.error(err.message);
  process.exit(1);
}
